func WithTimeout(parent Context[](https://pkg.go.dev/context#Context), timeout time[](https://pkg.go.dev/time).Duration[](https://pkg.go.dev/time#Duration)) (Context[](https://pkg.go.dev/context#Context), CancelFunc[](https://pkg.go.dev/context#CancelFunc))
